package com.sotewallremover;

import com.google.common.collect.ImmutableSet;
import java.util.function.Function;
import lombok.AllArgsConstructor;
import java.util.Set;

@AllArgsConstructor
public enum Bosses {
	NEX(ImmutableSet.of(11600, 11601), ImmutableSet.of(26493, 26438, 26435, 37491, 26425, 26423, 42945), ImmutableSet.of(26423, 26425, 26426, 26424, 26435, 26438, 26439, 26437, 26436, 6926), SoteWallConfig::HideNex),
	SOTE(ImmutableSet.of(13123), ImmutableSet.of(33044, 33046, 33047, 33048, 33049, 33050, 33051, 33052, 33059, 33058, 33057, 33056, 33055, 33054, 33053), null, SoteWallConfig::HideSote),
	GAUNTLET(ImmutableSet.of(7512), ImmutableSet.of(36095, 36097, 36098, 36099, 36100, 36103, 36104, 36105), null, SoteWallConfig::HideGauntlet),
	CORRUPTED_GAUNTLET(ImmutableSet.of(7768), ImmutableSet.of(35992, 35994, 35995, 35996, 35997, 36002), null, SoteWallConfig::HideGauntlet),
	VETION(ImmutableSet.of(13215, 7604),  ImmutableSet.of(46921, 46928, 47176, 46927), ImmutableSet.of(20980, 46914, 46915, 46916), SoteWallConfig::HideVetion);

	private final Set<Integer> regions;
	public final Set<Integer> gameObj;
	public final Set<Integer> wallObj;
	private final Function<SoteWallConfig, Boolean> configChecker;

	public boolean isEnabled(SoteWallConfig config) {
		return configChecker.apply(config);
	}

	public static Bosses inRegion(int regionId) {
		for (Bosses b : Bosses.values())
		{
			if (b.regions.contains(regionId)) {
				return b;
			}
		}
		return null;
	}

	public static Bosses inRegion(int regionId, SoteWallConfig config) {
		for (Bosses b : Bosses.values())
		{
			if (b.isEnabled(config) && b.regions.contains(regionId)) {
				return b;
			}
		}
		return null;
	}
}

package com.sotewallremover;

import lombok.Getter;
import lombok.Setter;
import net.runelite.api.GameObject;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.TileObject;
import net.runelite.client.callback.RenderCallback;

import javax.inject.Inject;
import java.util.HashSet;
import java.util.Set;

public class NewObjectHider implements RenderCallback {

    public Set<Integer> gameObjectReference = new HashSet<>();
    public Set<Integer> wallObjectReference = new HashSet<>();
    public Bosses boss;

    @Inject
    NewObjectHider(){}

    @Override
    public boolean drawTile(Scene scene, Tile tile)
    {
        if (boss != null && tile.getWallObject() != null)
        {
            boolean isMarkedForDeletion = wallObjectReference.contains(tile.getWallObject().getId());
            if (isMarkedForDeletion)
                scene.removeTile(tile);
            return !isMarkedForDeletion;
        }
        return RenderCallback.super.drawTile(scene, tile);
    }

    @Override
    public boolean drawObject(Scene scene, TileObject object)
    {
        if (boss != null && object instanceof GameObject)
        {
            return !gameObjectReference.contains(object.getId());
        }
        return RenderCallback.super.drawObject(scene, object);
    }
}

package com.sotewallremover;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

import static com.sotewallremover.SoteWallConfig.configName;

@ConfigGroup(configName)
public interface SoteWallConfig extends Config
{
	String configName = "BossWallConfig";
	@ConfigItem(
			keyName = "hideSote",
			name = "Hide Walls At Soteseg",
			description = "",
			position = 0
	)
	default boolean HideSote()
	{
		return true;
	}
	@ConfigItem(
			keyName = "hideNex",
			name = "Hide Walls At Nex",
			description = "",
			position = 1
	)
	default boolean HideNex()
	{
		return true;
	}
	@ConfigItem(
			keyName = "hideGauntlet",
			name = "Hide Walls At Gauntlet",
			description = "",
			position = 2
	)
	default boolean HideGauntlet()
	{
		return false;
	}
	@ConfigItem(
			keyName = "hideVetion",
			name = "Hide Walls At Vet'ion",
			description = "",
			position = 3
	)
	default boolean HideVetion()
	{
		return false;
	}
}

package com.sotewallremover;

import com.google.inject.Provides;
import javax.inject.Inject;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.WallObjectSpawned;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.callback.RenderCallbackManager;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@Slf4j
@PluginDescriptor(
		name = "Boss Wall Remover",
		description = "Removes annoying walls at various bosses",
		tags = {"tob", "theatre of blood", "nex", "bossing"}
)
public class SoteWallPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private SoteWallConfig config;

	@Inject
	private ClientThread clientThread;

    @Inject
    private NewObjectHider callback;

    @Inject
    private RenderCallbackManager renderCallbackManager;

	@Override
	protected void startUp() throws Exception
	{
        renderCallbackManager.register(callback);
		clientThread.invoke(() ->
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				client.setGameState(GameState.LOADING);
			}
		});
	}

	@Override
	protected void shutDown() throws Exception
	{
        renderCallbackManager.unregister(callback);
		clientThread.invoke(() ->
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				client.setGameState(GameState.LOADING);
			}
		});
		CleanUp(true);
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		int regionId = WorldPoint.fromLocalInstance(client, client.getLocalPlayer().getLocalLocation()).getRegionID();
		Bosses boss = Bosses.inRegion(regionId, config);

		if (boss == null)
		{
			CleanUp(true);
			return;
		}

		if (callback.boss == boss) //Boss hasn't changed so ignore
		{
			return;
		}

		callback.boss = boss;
		CleanUp(false);

		if (boss.gameObj != null)
			callback.gameObjectReference.addAll(boss.gameObj);
		if (boss.wallObj != null)
			callback.wallObjectReference.addAll(boss.wallObj);

		client.setGameState(GameState.LOADING); //This is necessary to properly hide scenery, the callback doesn't seem to run until I do this for some reason
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (event.getGroup().equals(SoteWallConfig.configName))
		{
			int regionId = WorldPoint.fromLocalInstance(client, client.getLocalPlayer().getLocalLocation()).getRegionID();
			Bosses boss = Bosses.inRegion(regionId);

			if (boss == null)
			{
				return;
			}

			CleanUp(true);
			//Just forces a map load to hide stuff
			clientThread.invoke(() ->
			{
				if (client.getGameState() == GameState.LOGGED_IN)
				{
					client.setGameState(GameState.LOADING);
				}
			});
		}
	}

	private void CleanUp(boolean clearBoss) {
		if (clearBoss)
			callback.boss = null;
		callback.gameObjectReference.clear();
		callback.wallObjectReference.clear();
	}

	@Provides
	SoteWallConfig provideConfig(ConfigManager configManager) {
		return configManager.getConfig(SoteWallConfig.class);
	}
}

